# Tree-only assembly enumeration; use static deltas and keep all exact arrangements
node_count=0; tree_best=-1; tree_sols=[]; tree_memo=set(); t0=time.time()
def candidate_tree(k,pl):
  # candidate bases from pair of markers matching any existing point
  existing={}
  for kk,b in pl.items():
    for p in translate(parts[kk]['marks'],b): existing.setdefault(p,set()).add(kk)
  poss=set()
  for mr,mc in parts[k]['marks']:
    for (er,ec) in existing:
      poss.add((er-mr,ec-mc))
  out=[]
  for base in poss:
    sh=translate(parts[k]['shape'],base); mk=translate(parts[k]['marks'],base)
    if any(not(0<=r<B and 0<=c<B) for r,c in sh|mk): continue
    old_shapes={kk:translate(parts[kk]['shape'],b) for kk,b in pl.items()}
    old_marks={kk:translate(parts[kk]['marks'],b) for kk,b in pl.items()}
    if any(sh&s for s in old_shapes.values()):continue
    if any(sh&m for m in old_marks.values()):continue
    if any(mk&s for s in old_shapes.values()):continue
    overlaps={kk:len(mk&m) for kk,m in old_marks.items() if mk&m}
    # exactly one previous object contacts (tree expansion); don't allow same coordinate overlaps with >1 objects
    if len(overlaps)==1:
      parent,n=next(iter(overlaps.items()))
      # each marker point only pair with one old mark point; no triple allowed
      if any(len(existing[p])>1 for p in mk if p in existing): continue
      out.append((base,parent,n))
  return out

